import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


triu_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""


triu_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <mma.h>
#include <cute/tensor.hpp>

#include <algorithm>
#include <limits>
#include <type_traits>

using namespace cute;

// Optimization: upgrade the warp-level tiling from one 32x64 sub-tile
// per warp (8 warps, 256 threads) to one 64x64 sub-tile per warp (4
// warps, 128 threads). Each warp now owns a 4x4 grid of 16x16x8 TF32
// WMMA fragments, doubling the mma:shared-memory-load ratio and
// halving shared-memory traffic per FLOP (better tensor-core
// utilization at the same 128x128x32 CTA tile and cp.async pipeline).
constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 32;
constexpr int Threads = 128;
// Shared-memory row strides are multiples of 8 floats (32 bytes) so that
// every WMMA fragment row stays 32-byte aligned.
constexpr int LDA = BK + 8;
constexpr int LDB = BN + 8;
constexpr int AStageElems = BM * LDA;
constexpr int BStageElems = BK * LDB;
// Total dynamic shared memory: NumStages pipelined stages each for sA
// and sB (sA at smem[0, NumStages*AStageElems), sB at
// smem[NumStages*AStageElems, end)). NumStages is a kernel template
// parameter so the host wrapper can pick the deepest cp.async
// pipeline whose shared-memory footprint fits the device's opt-in
// limit (4 stages ~= 148 KB, 3 ~= 111 KB, 2 ~= 74 KB).
constexpr int EpilogueFloats = 4 * 64 * 64;
template <int NumStages>
constexpr size_t SharedBytesFor() {
  return static_cast<size_t>(NumStages * (AStageElems + BStageElems) + 8) *
         sizeof(float);
}

#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
using VectorCopyAtom = Copy_Atom<SM80_CP_ASYNC_CACHEGLOBAL<cute::uint128_t>, float>;
constexpr bool HasCpAsync = true;
#else
using VectorCopyAtom = Copy_Atom<UniversalCopy<cute::uint128_t>, float>;
constexpr bool HasCpAsync = false;
#endif

template <int NumStages>
__global__ __launch_bounds__(Threads, 1)
void triu_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K)
{
  static_assert(NumStages >= 2, "the pipeline needs at least double buffering");
  static_assert(NumStages * (AStageElems + BStageElems) + 8 >= EpilogueFloats,
                "shared-memory stages must also fit the epilogue staging buffers");
  extern __shared__ float smem_raw[];
  // Align the dynamic shared-memory base to 32 bytes so every WMMA
  // fragment row remains 32-byte aligned (LDA/LDB are multiples of 8
  // floats, i.e. 32 bytes).
  float* smem = reinterpret_cast<float*>(
      (reinterpret_cast<size_t>(smem_raw) + 31) & ~static_cast<size_t>(31));
  float* sA_base = smem;
  float* sB_base = smem + NumStages * AStageElems;

  const int tid = threadIdx.x;
  const int bm = blockIdx.y;
  const int bn = blockIdx.x;
  const int m0 = bm * BM;
  const int n0 = bn * BN;

  Tensor mA = make_tensor(
      make_gmem_ptr(A),
      make_shape(M, K),
      make_stride(static_cast<int64_t>(K), Int<1>{})
  );
  Tensor mB = make_tensor(
      make_gmem_ptr(B),
      make_shape(K, N),
      make_stride(static_cast<int64_t>(N), Int<1>{})
  );
  Tensor mC = make_tensor(
      make_gmem_ptr(C),
      make_shape(M, N),
      make_stride(static_cast<int64_t>(N), Int<1>{})
  );

  Tensor gA_all = local_tile(
      mA, make_shape(Int<BM>{}, Int<BK>{}), make_coord(bm, _)
  );
  Tensor gB_all = local_tile(
      mB, make_shape(Int<BK>{}, Int<BN>{}), make_coord(_, bn)
  );
  Tensor gC = local_tile(
      mC, make_shape(Int<BM>{}, Int<BN>{}), make_coord(bm, bn)
  );

  // Padded leading dimension keeps the vectorized (float4) shared-memory
  // reads in the compute loop free of bank conflicts.
  auto sA_layout = make_layout(
      make_shape(Int<BM>{}, Int<BK>{}),
      make_stride(Int<LDA>{}, Int<1>{})
  );
  auto sB_store_layout = make_layout(
      make_shape(Int<BK>{}, Int<BN>{}),
      make_stride(Int<LDB>{}, Int<1>{})
  );
  // Warp-level tiling: 4 warps arranged 2x2 cover the 128x128 block tile.
  // Each warp owns a 64x64 sub-tile; on the pre-sm_80 fallback path each
  // lane owns a 16x8 register sub-tile (rows strided by 4, 8 contiguous
  // columns).
  const int warp = tid >> 5;
  const int lane = tid & 31;
  const int warp_m = warp >> 1;
  const int warp_n = warp & 1;
  const int lane_m = lane >> 3;
  const int lane_n = lane & 7;
  const int row0 = warp_m * 64 + lane_m;
  const int col0 = warp_n * 64 + lane_n * 8;
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  // Tensor-core path (sm_80+): each warp computes a 64x64 sub-tile as
  // 4x4 WMMA fragments of shape 16x16x8 using TF32 tensor cores with
  // FP32 accumulation. The padded sA[BM][BK] / sB[BK][BN] shared-memory
  // layouts feed the fragments directly as row_major operands.
  nvcuda::wmma::fragment<nvcuda::wmma::accumulator, 16, 16, 8, float>
      acc_frag[4][4];
  #pragma unroll
  for (int mi = 0; mi < 4; ++mi) {
    #pragma unroll
    for (int ni = 0; ni < 4; ++ni) {
      nvcuda::wmma::fill_fragment(acc_frag[mi][ni], 0.0f);
    }
  }
  auto compute_tile = [&](int stage) {
    const float* __restrict__ sA = sA_base + stage * AStageElems;
    const float* __restrict__ sB = sB_base + stage * BStageElems;
    #pragma unroll
    for (int k = 0; k < BK; k += 8) {
      nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, 16, 16, 8,
                             nvcuda::wmma::precision::tf32,
                             nvcuda::wmma::row_major> a_frag[4];
      nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, 16, 16, 8,
                             nvcuda::wmma::precision::tf32,
                             nvcuda::wmma::row_major> b_frag[4];
      #pragma unroll
      for (int mi = 0; mi < 4; ++mi) {
        nvcuda::wmma::load_matrix_sync(
            a_frag[mi], &sA[(warp_m * 64 + mi * 16) * LDA + k], LDA);
      }
      #pragma unroll
      for (int ni = 0; ni < 4; ++ni) {
        nvcuda::wmma::load_matrix_sync(
            b_frag[ni], &sB[k * LDB + warp_n * 64 + ni * 16], LDB);
      }
      #pragma unroll
      for (int mi = 0; mi < 4; ++mi) {
        #pragma unroll
        for (int ni = 0; ni < 4; ++ni) {
          nvcuda::wmma::mma_sync(acc_frag[mi][ni], a_frag[mi], b_frag[ni],
                                 acc_frag[mi][ni]);
        }
      }
    }
  };
#else
  float rC[16][8];
  #pragma unroll
  for (int i = 0; i < 16; ++i) {
    #pragma unroll
    for (int j = 0; j < 8; ++j) {
      rC[i][j] = 0.0f;
    }
  }
  auto compute_tile = [&](int stage) {
    const float* __restrict__ sA = sA_base + stage * AStageElems;
    const float* __restrict__ sB = sB_base + stage * BStageElems;
    float a_frag[16][4];
    float b_frag[8][4];
    #pragma unroll
    for (int k = 0; k < BK; k += 4) {
      #pragma unroll
      for (int i = 0; i < 16; ++i) {
        const float4 v = *reinterpret_cast<const float4*>(
            &sA[(row0 + 4 * i) * LDA + k]);
        a_frag[i][0] = v.x;
        a_frag[i][1] = v.y;
        a_frag[i][2] = v.z;
        a_frag[i][3] = v.w;
      }
      #pragma unroll
      for (int kk = 0; kk < 4; ++kk) {
        #pragma unroll
        for (int j = 0; j < 8; j += 4) {
          const float4 v = *reinterpret_cast<const float4*>(
              &sB[(k + kk) * LDB + col0 + j]);
          b_frag[j + 0][kk] = v.x;
          b_frag[j + 1][kk] = v.y;
          b_frag[j + 2][kk] = v.z;
          b_frag[j + 3][kk] = v.w;
        }
      }
      #pragma unroll
      for (int kk = 0; kk < 4; ++kk) {
        #pragma unroll
        for (int i = 0; i < 16; ++i) {
          #pragma unroll
          for (int j = 0; j < 8; ++j) {
            rC[i][j] += a_frag[i][kk] * b_frag[j][kk];
          }
        }
      }
    }
  };
#endif

  const int m_end = min(M, m0 + BM);
  const int n_end = min(N, n0 + BN);
  const bool tile_has_upper = (m0 < n_end);

  if (tile_has_upper) {
    // For upper-triangular A and B:
    // C(i,j) = sum_{k=i}^{j} A(i,k) B(k,j).
    const int k_begin = (m0 / BK) * BK;
    const int k_end = min(K, n_end);

    const bool use_vector_path =
        (M % BM == 0) && (N % BN == 0) && (K % BK == 0) && ((K & 3) == 0);

    if (use_vector_path) {
      auto copy_thr_A = make_layout(
          make_shape(Int<32>{}, Int<4>{}),
          make_stride(Int<4>{}, Int<1>{})
      );
      auto copy_val_A = make_layout(
          make_shape(Int<1>{}, Int<4>{}),
          make_stride(Int<4>{}, Int<1>{})
      );
      auto tiled_copy_A = make_tiled_copy(
          VectorCopyAtom{}, copy_thr_A, copy_val_A
      );
      auto copy_thr_B = make_layout(
          make_shape(Int<8>{}, Int<16>{}),
          make_stride(Int<16>{}, Int<1>{})
      );
      auto copy_val_B = make_layout(
          make_shape(Int<1>{}, Int<4>{}),
          make_stride(Int<4>{}, Int<1>{})
      );
      auto tiled_copy_B = make_tiled_copy(
          VectorCopyAtom{}, copy_thr_B, copy_val_B
      );

      auto load_tile = [&](int kt, int stage) {
        Tensor gA = gA_all(_, _, kt);
        Tensor gB = gB_all(_, _, kt);

        Tensor sA = make_tensor(
            make_smem_ptr(sA_base + stage * AStageElems), sA_layout
        );
        Tensor sB_store = make_tensor(
            make_smem_ptr(sB_base + stage * BStageElems), sB_store_layout
        );

        auto thr_copy_A = tiled_copy_A.get_thread_slice(tid);
        Tensor tAgA = thr_copy_A.partition_S(gA);
        Tensor tAsA = thr_copy_A.partition_D(sA);
        copy(tiled_copy_A, tAgA, tAsA);

        auto thr_copy_B = tiled_copy_B.get_thread_slice(tid);
        Tensor tBgB = thr_copy_B.partition_S(gB);
        Tensor tBsB = thr_copy_B.partition_D(sB_store);
        copy(tiled_copy_B, tBgB, tBsB);

        if constexpr (HasCpAsync) {
          cp_async_fence();
        }
      };

      const int kt_begin = k_begin / BK;
      const int num_k_tiles = (k_end - k_begin + BK - 1) / BK;
      // Software-pipeline prologue: fill the first NumStages-1 stages so
      // that up to NumStages-1 global-memory tiles are in flight while
      // the compute loop below consumes the oldest one.
      #pragma unroll
      for (int s = 0; s < NumStages - 1; ++s) {
        if (s < num_k_tiles) {
          load_tile(kt_begin + s, s);
        }
        if constexpr (HasCpAsync) {
          cp_async_fence();
        }
      }
      for (int kt = 0; kt < num_k_tiles; ++kt) {
        // Wait until the oldest in-flight tile has landed (no more than
        // NumStages-2 groups may remain in flight), then publish it.
        if constexpr (HasCpAsync) {
          cp_async_wait<NumStages - 2>();
        }
        __syncthreads();
        compute_tile(kt % NumStages);
        // Prefetch the tile NumStages-1 iterations ahead into the stage
        // that was consumed NumStages-1 iterations ago. Every thread
        // passed the barrier above after finishing that stage, so the
        // overwrite is race-free.
        const int kt_next = kt + NumStages - 1;
        if (kt_next < num_k_tiles) {
          load_tile(kt_begin + kt_next, kt_next % NumStages);
        }
        if constexpr (HasCpAsync) {
          cp_async_fence();
        }
      }
    } else {
      Tensor sA = make_tensor(make_smem_ptr(sA_base), sA_layout);
      Tensor sB_store = make_tensor(make_smem_ptr(sB_base), sB_store_layout);

      for (int k0 = k_begin; k0 < k_end; k0 += BK) {
        for (int idx = tid; idx < BM * BK; idx += Threads) {
          const int tm = idx / BK;
          const int tk = idx - tm * BK;
          const int m = m0 + tm;
          const int k = k0 + tk;
          sA(tm, tk) = (m < M && k < K) ? mA(m, k) : 0.0f;
        }

        for (int idx = tid; idx < BK * BN; idx += Threads) {
          const int tk = idx / BN;
          const int tn = idx - tk * BN;
          const int k = k0 + tk;
          const int n = n0 + tn;
          sB_store(tk, tn) = (k < K && n < N) ? mB(k, n) : 0.0f;
        }

        __syncthreads();
        compute_tile(0);
        __syncthreads();
      }
    }
  }

#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
  const bool full_tile =
      (m0 + BM <= M) && (n0 + BN <= N) && ((N & 7) == 0);
  if (full_tile && (m0 + BM <= n0)) {
    // Tile lies strictly above the diagonal: the triangular mask is a
    // no-op and every 16x16 fragment is fully in bounds, so the
    // accumulators can be stored straight to global memory.
    #pragma unroll
    for (int mi = 0; mi < 4; ++mi) {
      #pragma unroll
      for (int ni = 0; ni < 4; ++ni) {
        nvcuda::wmma::store_matrix_sync(
            &mC(m0 + warp_m * 64 + mi * 16, n0 + warp_n * 64 + ni * 16),
            acc_frag[mi][ni], N, nvcuda::wmma::mem_row_major);
      }
    }
  } else {
    // Reuse the idle shared-memory stages as per-warp staging buffers
    // (4 * 64 * 64 floats fit inside the pipelined stages) so the
    // triangular mask and bounds checks can be applied element by element.
    float* stage_buf = smem + warp * (64 * 64);
    #pragma unroll
    for (int mi = 0; mi < 4; ++mi) {
      #pragma unroll
      for (int ni = 0; ni < 4; ++ni) {
        nvcuda::wmma::store_matrix_sync(stage_buf + mi * 16 * 64 + ni * 16,
                                        acc_frag[mi][ni], 64,
                                        nvcuda::wmma::mem_row_major);
      }
    }
    __syncwarp();
    for (int e = lane; e < 64 * 64; e += 32) {
      const int r = e >> 6;
      const int c = e & 63;
      const int m = m0 + warp_m * 64 + r;
      const int n = n0 + warp_n * 64 + c;
      if (m < M && n < N) {
        mC(m, n) = (m <= n) ? stage_buf[e] : 0.0f;
      }
    }
  }
#else
  #pragma unroll
  for (int i = 0; i < 16; ++i) {
    const int m = m0 + row0 + 4 * i;
    if (m < M) {
      #pragma unroll
      for (int j = 0; j < 8; ++j) {
        const int n = n0 + col0 + j;
        if (n < N) {
          mC(m, n) = (m <= n) ? rC[i][j] : 0.0f;
        }
      }
    }
  }
#endif
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be two-dimensional");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32 tensors");
  TORCH_CHECK(A.is_contiguous() && B.is_contiguous(),
              "A and B must be contiguous");

  const int64_t M = A.size(0);
  const int64_t K = A.size(1);
  const int64_t N = B.size(1);

  TORCH_CHECK(B.size(0) == K, "A and B have incompatible shapes");
  TORCH_CHECK(M == K && K == N, "A and B must be square matrices of the same size");
  TORCH_CHECK(N <= std::numeric_limits<int>::max(), "Matrix dimension is too large");

  auto C = torch::empty({M, N}, A.options());

  const int n = static_cast<int>(N);
  const dim3 block(Threads);
  const dim3 grid(
      static_cast<unsigned>((n + BN - 1) / BN),
      static_cast<unsigned>((n + BM - 1) / BM)
  );
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  // Query the device's opt-in dynamic shared-memory limit and pick the
  // deepest cp.async pipeline that fits. 4 stages (~148 KB) needs
  // A100/H100-class parts; 3 stages (~111 KB); 2 stages (~74 KB) fits
  // sm_86/sm_89-class GPUs (~100 KB opt-in max).
  int max_smem = 0;
  const cudaError_t attr_err = cudaDeviceGetAttribute(
      &max_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin,
      static_cast<int>(A.get_device()));
  TORCH_CHECK(attr_err == cudaSuccess,
              "Failed to query shared memory limit: ",
              cudaGetErrorString(attr_err));
  const auto launch = [&](auto stages_const) -> bool {
    constexpr int S = decltype(stages_const)::value;
    constexpr size_t bytes = SharedBytesFor<S>();
    if (bytes > static_cast<size_t>(max_smem)) {
      return false;
    }
    static const bool configured = [] {
      return cudaFuncSetAttribute(
                 triu_matmul_kernel<S>,
                 cudaFuncAttributeMaxDynamicSharedMemorySize,
                 static_cast<int>(bytes)) == cudaSuccess;
    }();
    if (!configured) {
      return false;
    }
    triu_matmul_kernel<S><<<grid, block, bytes, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        n, n, n
    );
    return true;
  };
  const bool launched =
      launch(std::integral_constant<int, 4>{}) ||
      launch(std::integral_constant<int, 3>{}) ||
      launch(std::integral_constant<int, 2>{});
  TORCH_CHECK(launched,
              "No triu_matmul pipeline depth fits in ", max_smem,
              " bytes of shared memory");
  const cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "triu_matmul_kernel launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""


triu_matmul_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=triu_cpp_decl,
    cuda_sources=triu_cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = triu_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.triu_matmul(A, B)

