    const float* __restrict__ sB = sB_base + stage * BStageElems;
    float a_frag[8][4];
    float b_frag[8][4];
    #pragma unroll
    for (int k = 0; k < BK; k += 4) {
      #pragma unroll
      for (int i = 0; i < 8; ++i) {
        const float4 v = *reinterpret_cast<const float4*>(
            &sA[(row0 + 4 * i) * LDA + k]);
        a_frag[i][0] = v.x;
        a_frag[i][1] = v.y;
        a_frag[i][2] = v.z;
        a_frag[i][3] = v.w;
