      #pragma unroll
      for (int kk = 0; kk < 4; ++kk) {
        #pragma unroll
        for (int j = 0; j < 8; j += 4) {
          const float4 v = *reinterpret_cast<const float4*>(
              &sB[(k + kk) * LDB + col0 + j]);
          b_frag[j + 0][kk] = v.x;
          b_frag[j + 1][kk] = v.y;
          b_frag[j + 2][kk] = v.z;
          b_frag[j + 3][kk] = v.w;
        }
      }
      #pragma unroll
      for (int kk = 0; kk < 4; ++kk) {
        #pragma unroll
        for (int i = 0; i < 8; ++i) {
          #pragma unroll
          for (int j = 0; j < 8; ++j) {
