          make_shape(Int<64>{}, Int<4>{}),
          make_stride(Int<4>{}, Int<1>{})
      );
      auto copy_val_A = make_layout(
          make_shape(Int<1>{}, Int<4>{}),
          make_stride(Int<4>{}, Int<1>{})
      );
      auto tiled_copy_A = make_tiled_copy(
          VectorCopyAtom{}, copy_thr_A, copy_val_A
      );
      auto copy_thr_B = make_layout(
          make_shape(Int<16>{}, Int<16>{}),
          make_stride(Int<16>{}, Int<1>{})
      );
      auto copy_val_B = make_layout(
          make_shape(Int<1>{}, Int<4>{}),
          make_stride(Int<4>{}, Int<1>{})
      );
