// per warp (8 warps, 256 threads) to one 64x64 sub-tile per warp (4
// warps, 128 threads). Each warp now owns a 4x4 grid of 16x16x8 TF32
// WMMA fragments, doubling the mma:shared-memory-load ratio and
// halving shared-memory traffic per FLOP (better tensor-core
// utilization at the same 128x128x32 CTA tile and cp.async pipeline).
constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 32;
constexpr int Threads = 128;
// Shared-memory row strides are multiples of 8 floats (32 bytes) so that
// every WMMA fragment row stays 32-byte aligned.
constexpr int LDA = BK + 8;
constexpr int LDB = BN + 8;
constexpr int AStageElems = BM * LDA;
constexpr int BStageElems = BK * LDB;
