              &sB[(k + kk) * LDB + col0 + j]);
          b_frag[j + 0][kk] = v.x;
          b_frag[j + 1][kk] = v.y;
          b_frag[j + 2][kk] = v.z;
          b_frag[j + 3][kk] = v.w;
        }
      }
