    // (8 * 32 * 64 floats fit inside SharedFloats) so the triangular
    // mask and bounds checks can be applied element by element.
    float* stage_buf = smem + warp * (32 * 64);
    #pragma unroll
    for (int mi = 0; mi < 2; ++mi) {
      #pragma unroll
      for (int ni = 0; ni < 4; ++ni) {
